// Unshown synthetic UI verification; all power calls use a fake backend.
using System;using System.Collections.Generic;using System.Linq;using System.Reflection;using System.Windows;using System.Windows.Controls;using System.Windows.Media;using RogControl;
internal static class WindowsToolsTests {
 sealed class FakePower:IWindowsPowerBackend {public int Writes;public Guid Active=new Guid("10000000-0000-0000-0000-000000000000");public uint Ac=2,Dc=3;public IList<WindowsPowerScheme> EnumerateSchemes(){return new[]{new WindowsPowerScheme(Active,"测试电源计划"),new WindowsPowerScheme(new Guid("20000000-0000-0000-0000-000000000000"),"另一电源计划")};}public Guid GetActiveScheme(){return Active;}public uint ReadBoost(Guid scheme,bool ac){return ac?Ac:Dc;}public void WriteBoost(Guid scheme,bool ac,uint value){Writes++;if(ac)Ac=value;else Dc=value;}public void SetActiveScheme(Guid scheme){Writes++;Active=scheme;}}
 static readonly BindingFlags Hidden=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;
 static int count;static void Check(bool yes,string message){count++;if(!yes)throw new Exception(message);}
 static void Set(MainWindow w,string field,object value){typeof(MainWindow).GetField(field,Hidden).SetValue(w,value);}
 static object Get(MainWindow w,string field){return typeof(MainWindow).GetField(field,Hidden).GetValue(w);}
 static void Invoke(MainWindow w,string method,params object[] args){typeof(MainWindow).GetMethod(method,Hidden).Invoke(w,args);}
 static IEnumerable<DependencyObject> Walk(DependencyObject item){yield return item;for(int i=0;i<VisualTreeHelper.GetChildrenCount(item);i++)foreach(var child in Walk(VisualTreeHelper.GetChild(item,i)))yield return child;}
 [STAThread]static void Main(){try{var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};var w=new MainWindow(true);var fake=new FakePower();var service=new WindowsPowerService(fake);Set(w,"windowsPowerService",service);Invoke(w,"SetWindowsPowerRead",service.ReadSnapshot(),false);
  foreach(int width in new[]{1180,1538}){Invoke(w,"ShowPage","Windows 电源");var root=(FrameworkElement)w.Content;root.Measure(new Size(width,826));root.Arrange(new Rect(0,0,width,826));root.UpdateLayout();var nodes=Walk(root).ToArray();Check(nodes.OfType<TextBlock>().Any(t=>t.Text=="当前电源计划：测试电源计划"),"Actual snapshot name is displayed");var combos=nodes.OfType<ComboBox>().ToArray();Check(combos.Length==3,"Scheme and separate AC/DC selectors exist");Check(combos[0].Items.Count==2&&combos[1].Items.Count==7&&combos[2].Items.Count==7,"Only enumerated plans and documented boost values are selectable");Check(combos[1].SelectedIndex==2&&combos[2].SelectedIndex==3,"AC/DC current values are separate");Check(nodes.OfType<Button>().Where(b=>Convert.ToString(b.Content).StartsWith("应用")).All(b=>!b.IsEnabled),"Render-only view cannot apply settings");foreach(var combo in combos)Check(combo.ActualWidth<width-248-44,"Controls fit the original content width");combos[1].SelectedIndex=0;Check((uint?)Get(w,"windowsPowerDraftAc")==0&&fake.Writes==0,"Editing boost stays a local draft");Invoke(w,"SetWindowsPowerRead",service.ReadSnapshot(),false);}
  Set(w,"windowsSystemWriting",true);Check(!w.CanPreviewReload,"Writing blocks replacement through the busy transaction guard");Set(w,"windowsSystemWriting",false);
  var receipt=service.ChangeCpuBoost(fake.Active,0,null);Set(w,"windowsPowerUndo",receipt.RestorePoint);Check(!w.CanPreviewReload,"Pending manual restore point survives by delaying preview replacement");Set(w,"windowsPowerUndo",null);Check(w.CanPreviewReload,"Choosing to keep a setting permits preview replacement");Check(fake.Writes>0,"Receipt test uses only fake mutations");
  var failed=new WindowsPowerChangeResult();typeof(WindowsPowerChangeResult).GetProperty("RestorePoint").SetValue(failed,receipt.RestorePoint,null);typeof(WindowsPowerChangeResult).GetProperty("Error").SetValue(failed,"synthetic rollback failure",null);Invoke(w,"WindowsPowerChanged",failed);Check(Object.ReferenceEquals(Get(w,"windowsPowerUndo"),receipt.RestorePoint),"Failed mutation retains its issued manual restore point");Check(Get(w,"windowsPower")==null,"Failed mutation without current readback clears the old current snapshot");Check(!w.CanPreviewReload,"Unresolved failed mutation blocks losing restore ownership");Invoke(w,"ShowPage","Windows 电源");var failedRoot=(FrameworkElement)w.Content;failedRoot.Measure(new Size(1180,826));failedRoot.Arrange(new Rect(0,0,1180,826));failedRoot.UpdateLayout();Check(Walk(failedRoot).OfType<Button>().Any(b=>Convert.ToString(b.Content)=="恢复修改前的设置"),"Restore remains reachable without a current snapshot");
  w.Close();app.Shutdown();Console.WriteLine("Windows tools UI: "+count+" synthetic checks passed; native calls 0, shown windows 0.");}catch(Exception ex){Console.Error.WriteLine(ex.InnerException??ex);Environment.ExitCode=1;}}
}
